1	// iCE40HX4K + 64 Mbit SDR SDRAM node (Class C case 2, issue #329).
2	// Six layers: signal / ground / signal / signal / ground / signal.
3	// Memory interface: soft SDR controller in the FPGA fabric (no hard DDR PHY),
4	// 16-bit data bus, 12-bit address, 2 bank bits, RAS/CAS/WE/CS/CKE, byte masks, clock.
5	//
6	// Stackup and impedance (assumptions, see REPORT.md):
7	//   L1 top copper 35 um, prepreg 0.10 mm er 4.3, L2 ground 15.2 um (1/2 oz),
8	//   core 0.30 mm, L3 signal, core 0.80 mm, L4 signal, core 0.30 mm, L5 ground, prepreg 0.10 mm, L6 bottom.
9	//   Outer microstrip over L2: 0.15 mm trace over 0.10 mm dielectric, er 4.3, t 35 um
10	//   Z0 = 87/sqrt(er+1.41) * ln(5.98 h / (0.8 w + t)) = 87/2.39 * ln(0.598/0.155) = 49 ohm (target 50 ohm).
11	// Input: 5 V +/-5 % -> max 5.25 V. Fuse hold 1.1 A. TVS PTVS6V0S1UR standoff 6.0 V > 5.25 V.
12	board "ice40_sdram_node" {
13	  layers 6
14	  manufacturer "jlc-advanced"
15	  requires via_in_pad
16	  revision "A"
17	
18	  stackup {
19	    copper 0.035mm
20	    insulator 0.1mm er 4.3 material "FR4"
21	    copper 0.0152mm
22	    insulator 0.3mm er 4.3 material "FR4"
23	    copper 0.0152mm
24	    insulator 0.8mm er 4.3 material "FR4"
25	    copper 0.0152mm
26	    insulator 0.3mm er 4.3 material "FR4"
27	    copper 0.0152mm
28	    insulator 0.1mm er 4.3 material "FR4"
29	    copper 0.035mm
30	  }
31	
32	  // ---- Net classes ---------------------------------------------------------
33	  netclass "PWR5"   { trace_width 0.6mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#d55e00" }
34	  netclass "PWR33"  { trace_width 0.4mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#e69f00" }
35	  netclass "PWR12"  { trace_width 0.25mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#cc79a7" }
36	  netclass "PLLSUP" { trace_width 0.2mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#f0e442" }
37	  netclass "GNDC"   { trace_width 0.3mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#444444" }
38	  netclass "LOWSPD" { trace_width 0.15mm clearance 0.127mm via_diameter 0.46mm via_drill 0.2mm edge_rate slow color "#009e73" }
39	  netclass "SDDATA" { trace_width 0.15mm clearance 0.127mm impedance 50ohm max_skew 10mm max_length 60mm via_diameter 0.46mm via_drill 0.2mm edge_rate fast color "#0072b2" }
40	  netclass "SDADDR" { trace_width 0.15mm clearance 0.127mm impedance 50ohm max_skew 10mm max_length 60mm via_diameter 0.46mm via_drill 0.2mm edge_rate fast color "#56b4e9" }
41	  netclass "SDCLK"  { trace_width 0.15mm clearance 0.127mm impedance 50ohm max_length 40mm via_diameter 0.46mm via_drill 0.2mm edge_rate fast color "#d62728" }
42	
43	  // ---- Power input and protection -----------------------------------------
44	  group "POWER INPUT" color "#c2410c" {
45	    component J1: connector "header_1x2" { placement_hint { edge: left priority: hard } }
46	    component F1: fuse "polyfuse_1r1a"
47	    component D1: diode "ptvs6v0s1ur" { placement_hint { near: "F1.p2" priority: hard } }
48	    component Q1: transistor "p_mosfet_si2301"
49	    component R1: resistor "r_generic_0603" value "10k"
50	    component C1: capacitor "c_generic_0805" value "10uF"
51	    notes "" {
52	      "5 V in, max 5.25 V. F1 hold 1.1 A, 16 V."
53	      "D1 standoff 6.0 V, above 5.25 V, before Q1."
54	      "Q1 P-MOSFET reverse stage, gate to GND."
55	    }
56	  }
57	
58	  // ---- 3.3 V and 1.2 V rails ------------------------------------------------
59	  group "3V3 RAIL" color "#b45309" {
60	    component U1: regulator "ams1117_3v3" value "AMS1117-3.3"
61	    component C2: capacitor "c_generic_0805" value "10uF" { placement_hint { near: "U1.vin" priority: hard } }
62	    component C3: capacitor "c_generic_0805" value "10uF" { placement_hint { near: "U1.vin" priority: hard } }
63	    component C4: capacitor "c_generic_0805" value "10uF" { placement_hint { near: "U1.vout" priority: hard } }
64	    component C5: capacitor "c_generic_0805" value "10uF" { placement_hint { near: "U1.vout" priority: hard } }
65	  }
66	
67	  group "1V2 CORE RAIL" color "#9d174d" {
68	    component U2: regulator "tlv70012_ddc" value "TLV70012DDCR"
69	    component C6: capacitor "c_generic_0603" value "1uF" { placement_hint { near: "U2.vin" priority: hard } }
70	    component C7: capacitor "c_generic_0603" value "1uF" { placement_hint { near: "U2.vout" priority: hard } }
71	  }
72	
73	  // ---- FPGA -----------------------------------------------------------------
74	  group "FPGA" color "#0072b2" {
75	    component U3: fpga "ice40hx4k_bg121_nc" { escape { method underpad } }
76	    component C10: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
77	    component C11: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
78	    component C12: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
79	    component C13: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
80	    component C14: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
81	    component C15: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
82	    component C16: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
83	    component C17: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
84	    component C18: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
85	    component C19: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
86	    component L1: inductor "ferrite_bead_0603" { placement_hint { near: "U3" priority: hard } }
87	    component C21: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
88	    component C22: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U3" priority: hard } }
89	    component C23: capacitor "c_generic_0603" value "1uF" { placement_hint { near: "U3" priority: hard } }
90	    notes "" {
91	      "Soft SDR controller, no hard DDR PHY. VPP_FAST (B10) left unconnected."
92	      "VCCPLL0/1 from 1.2 V through ferrite L1, 100 nF each and 1 uF bulk."
93	    }
94	  }
95	
96	  // ---- SDRAM ----------------------------------------------------------------
97	  group "SDRAM" color "#0a7d4a" {
98	    component U4: memory "is42s16400j_sdram" { escape { off } placement_hint { near: "U3" priority: hard } }
99	    component C30: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
100	    component C31: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
101	    component C32: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
102	    component C33: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
103	    component C34: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
104	    component C35: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
105	    component C36: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
106	    component C37: capacitor "c_generic_0805" value "10uF" { placement_hint { near: "U4" priority: hard } }
107	  }
108	
109	  group "SERIES TERMINATION" color "#7c3aed" {
110	    component RS1: resistor "r_generic_0402" value "22" { placement_hint { near: "U3.iot_198_gbin0" priority: hard } }
111	    component RS2: resistor "r_generic_0402" value "22" { placement_hint { near: "U3.iot_219" priority: hard } }
112	    component RS3: resistor "r_generic_0402" value "22" { placement_hint { near: "U3.iot_221" priority: hard } }
113	    component RS4: resistor "r_generic_0402" value "22" { placement_hint { near: "U3.iot_208" priority: hard } }
114	    component RS5: resistor "r_generic_0402" value "22" { placement_hint { near: "U3.iot_197_gbin1" priority: hard } }
115	    component RS6: resistor "r_generic_0402" value "22" { placement_hint { near: "U3.iot_177" priority: hard } }
116	    notes "" {
117	      "22 ohm in series at the FPGA end of CLK, CS, RAS, CAS, WE and CKE."
118	    }
119	  }
120	
121	  // ---- Configuration flash --------------------------------------------------
122	  group "CONFIGURATION" color "#1d4ed8" {
123	    component U5: memory "w25q128jvsiq_208mil" { escape { off } }
124	    component C40: capacitor "c_generic_0603" value "100nF" { placement_hint { near: "U5.vcc" priority: hard } }
125	    component R10: resistor "r_generic_0603" value "10k" { placement_hint { near: "U3.creset" priority: hard } }
126	    component R11: resistor "r_generic_0603" value "10k" { placement_hint { near: "U3.cdone" priority: hard } }
127	    component R12: resistor "r_generic_0603" value "10k" { placement_hint { near: "U5" priority: hard } }
128	    component R13: resistor "r_generic_0603" value "10k" { placement_hint { near: "U5.io2" priority: hard } }
129	    component R14: resistor "r_generic_0603" value "10k" { placement_hint { near: "U5" priority: hard } }
130	    notes "" {
131	      "Flash on the iCE40 master SPI pins SS_B, SCK, SDI, SDO."
132	      "CRESET_B and CDONE pulled up 10 k. WP and HOLD pulled up 10 k."
133	    }
134	  }
135	
136	  // ---- Status LEDs -----------------------------------------------------------
137	  group "STATUS LEDS" color "#be123c" {
138	    component D2: diode "led_red_0603"
139	    component R20: resistor "r_generic_0603" value "1k"
140	    component D3: diode "led_green_0603"
141	    component R21: resistor "r_generic_0603" value "1k"
142	    component Q2: transistor "ao3400a_nmos"
143	    component D4: diode "led_green_0603"
144	    component R22: resistor "r_generic_0603" value "1k"
145	    notes "" {
146	      "D2 3.3 V present. D3 lit when CDONE is high (Q2 buffers the open-drain pin). D4 user LED."
147	    }
148	  }
149	
150	  group "TEST POINTS" color "#475569" {
151	    component TP1: testpoint "testpoint_pad_1_5" { placement_hint { near: "Q1.s" priority: hard } }
152	    component TP2: testpoint "testpoint_pad_1_5" { placement_hint { near: "U4.vddq_3" priority: hard } }
153	    component TP3: testpoint "testpoint_pad_1_5" { placement_hint { near: "U2.vout" priority: hard } }
154	    component TP4: testpoint "testpoint_pad_1_5" { placement_hint { near: "U5.gnd" priority: hard } }
155	    component TP5: testpoint "testpoint_pad_1_5" { placement_hint { near: "U3.cdone" priority: hard } }
156	    component TP6: testpoint "testpoint_pad_1_5" { placement_hint { near: "U3.creset" priority: hard } }
157	    component TP7: testpoint "testpoint_pad_1_5" { placement_hint { near: "J1.p2" priority: hard } }
158	  }
159	
160	  group "MECHANICAL" color "#334155" {
161	    component H1: mounting_hole "mounting_hole_m2_5"
162	    component H2: mounting_hole "mounting_hole_m2_5"
163	  }
164	
165	  // ---- Rails ------------------------------------------------------------------
166	  power "GND" 0v class "GNDC" {
167	    J1.p2 D1.anode R1.p2 C1.p2
168	    U1.gnd C2.p2 C3.p2 C4.p2 C5.p2
169	    U2.gnd C6.p2 C7.p2
170	    U3.gnd U3.gnd_2 U3.gnd_3 U3.gnd_4 U3.gnd_5 U3.gnd_6 U3.gnd_7 U3.gnd_8 U3.gnd_9 U3.gnd_10 U3.gndpll0 U3.gndpll1
171	    U3.iob_103_cbsel0 U3.iob_104_cbsel1
172	    C10.p2 C11.p2 C12.p2 C13.p2 C14.p2 C15.p2 C16.p2 C17.p2 C18.p2 C19.p2 C21.p2 C22.p2 C23.p2
173	    U4.gndq_0 U4.gndq_1 U4.gndq_2 U4.gndq_3 U4.gnd_0 U4.gnd_1 U4.gnd_2
174	    C30.p2 C31.p2 C32.p2 C33.p2 C34.p2 C35.p2 C36.p2 C37.p2
175	    U5.gnd C40.p2
176	    D2.cathode D4.cathode Q2.s
177	    TP4.p1 TP7.p1
178	  }
179	
180	  net "VIN_RAW" class "PWR5" { J1.p1 F1.p1 }
181	  net "VIN_FUSED" class "PWR5" { F1.p2 D1.cathode Q1.d }
182	  net "Q1_GATE" class "LOWSPD" { Q1.g R1.p1 }
183	  power "+5V" 5v class "PWR5" { Q1.s C1.p1 U1.vin C2.p1 C3.p1 TP1.p1 }
184	
185	  power "+3V3" 3.3v class "PWR33" {
186	    U1.vout C4.p1 C5.p1 U2.vin C6.p1 U2.en
187	    U3.vccio_0 U3.vccio_1 U3.vccio_2 U3.vccio_3 U3.vccio_3_2 U3.vcc_spi U3.vpp_2v5
188	    C10.p1 C11.p1 C12.p1 C13.p1 C14.p1 C15.p1
189	    U4.vdd_0 U4.vdd_1 U4.vdd_2 U4.vddq_0 U4.vddq_1 U4.vddq_2 U4.vddq_3
190	    C30.p1 C31.p1 C32.p1 C33.p1 C34.p1 C35.p1 C36.p1 C37.p1
191	    U5.vcc C40.p1
192	    R10.p1 R11.p1 R12.p1 R13.p1 R14.p1 R20.p1 R21.p1
193	    TP2.p1
194	  }
195	
196	  power "+1V2" 1.2v class "PWR12" {
197	    U2.vout C7.p1
198	    U3.vcc U3.vcc_2 U3.vcc_3 U3.vcc_4
199	    C16.p1 C17.p1 C18.p1 C19.p1
200	    L1.p1 TP3.p1
201	  }
202	
203	  power "VCCPLL" 1.2v class "PLLSUP" {
204	    L1.p2 U3.vccpll0 U3.vccpll1 C21.p1 C22.p1 C23.p1
205	  }
206	
207	  // ---- Configuration nets ----------------------------------------------------
208	  net "SPI_SS_B" class "LOWSPD" { U3.iob_108_ss U5.cs R12.p2 }
209	  net "SPI_SCK"  class "LOWSPD" { U3.iob_107_sck U5.clk }
210	  net "SPI_SDO"  class "LOWSPD" { U3.iob_105_sdo U5.io0 }
211	  net "SPI_SDI"  class "LOWSPD" { U3.iob_106_sdi U5.io1 }
212	  net "FLASH_WP"   class "LOWSPD" { U5.io2 R13.p2 }
213	  net "FLASH_HOLD" class "LOWSPD" { U5.io3 R14.p2 }
214	  net "CRESET_B" class "LOWSPD" { U3.creset R10.p2 TP6.p1 }
215	  net "CDONE"    class "LOWSPD" { U3.cdone R11.p2 Q2.g TP5.p1 }
216	
217	  // ---- LEDs ---------------------------------------------------------------------
218	  net "LED_PWR"  class "LOWSPD" { R20.p2 D2.anode }
219	  net "LED_DONE_A" class "LOWSPD" { R21.p2 D3.anode }
220	  net "LED_DONE_K" class "LOWSPD" { D3.cathode Q2.d }
221	  net "LED_USER_R" class "LOWSPD" { U3.iob_56 R22.p1 }
222	  net "LED_USER_A" class "LOWSPD" { R22.p2 D4.anode }
223	
224	  // ---- SDRAM data bus ------------------------------------------------------------
225	  // Data bus on the left-face IOL balls (rings 1 and 2), facing the SDRAM.
226	  net "SD_DQ0"  class "SDDATA" { U3.iol_2a U4.dq0 }
227	  net "SD_DQ1"  class "SDDATA" { U3.iol_5b U4.dq1 }
228	  net "SD_DQ2"  class "SDDATA" { U3.iol_8b U4.dq2 }
229	  net "SD_DQ3"  class "SDDATA" { U3.iol_8a U4.dq3 }
230	  net "SD_DQ4"  class "SDDATA" { U3.iol_12a U4.dq4 }
231	  net "SD_DQ5"  class "SDDATA" { U3.iol_14a_gbin6 U4.dq5 }
232	  net "SD_DQ6"  class "SDDATA" { U3.iol_18a U4.dq6 }
233	  net "SD_DQ7"  class "SDDATA" { U3.iol_23a U4.dq7 }
234	  net "SD_DQ8"  class "SDDATA" { U3.iol_23b U4.dq8 }
235	  net "SD_DQ9"  class "SDDATA" { U3.iol_2b U4.dq9 }
236	  net "SD_DQ10" class "SDDATA" { U3.iol_5a U4.dq10 }
237	  net "SD_DQ11" class "SDDATA" { U3.iol_9a U4.dq11 }
238	  net "SD_DQ12" class "SDDATA" { U3.iol_10a U4.dq12 }
239	  net "SD_DQ13" class "SDDATA" { U3.iol_12b U4.dq13 }
240	  net "SD_DQ14" class "SDDATA" { U3.iol_14b U4.dq14 }
241	  net "SD_DQ15" class "SDDATA" { U3.iol_18b U4.dq15 }
242	
243	  // ---- SDRAM address, bank and byte masks (top-row and bottom-left outer balls) --------
244	  net "SD_A0"  class "SDADDR" { U3.iot_225 U4.a0 }
245	  net "SD_A1"  class "SDADDR" { U3.iot_222 U4.a1 }
246	  net "SD_A2"  class "SDADDR" { U3.iot_223 U4.a2 }
247	  net "SD_A3"  class "SDADDR" { U3.iot_211 U4.a3 }
248	  net "SD_A4"  class "SDADDR" { U3.iot_207 U4.a4 }
249	  net "SD_A5"  class "SDADDR" { U3.iot_206 U4.a5 }
250	  net "SD_A6"  class "SDADDR" { U3.iot_192 U4.a6 }
251	  net "SD_A7"  class "SDADDR" { U3.iot_190 U4.a7 }
252	  net "SD_A8"  class "SDADDR" { U3.iot_178 U4.a8 }
253	  net "SD_A9"  class "SDADDR" { U3.iot_170 U4.a9 }
254	  net "SD_A10" class "SDADDR" { U3.iot_168 U4.a10 }
255	  net "SD_A11" class "SDADDR" { U3.iot_174 U4.a11 }
256	  net "SD_BA0" class "SDADDR" { U3.iol_25b U4.ba0 }
257	  net "SD_BA1" class "SDADDR" { U3.iol_25a U4.ba1 }
258	  net "SD_LDQM" class "SDADDR" { U3.iob_61 U4.ldqm }
259	  net "SD_UDQM" class "SDADDR" { U3.iob_71 U4.udqm }
260	
261	  // ---- SDRAM command group and clock (22 ohm at the FPGA end) -------------------------
262	  net "SD_CS_F"  class "SDADDR" { U3.iot_219 RS2.p1 }
263	  net "SD_CS"    class "SDADDR" { RS2.p2 U4.cs }
264	  net "SD_RAS_F" class "SDADDR" { U3.iot_221 RS3.p1 }
265	  net "SD_RAS"   class "SDADDR" { RS3.p2 U4.ras }
266	  net "SD_CAS_F" class "SDADDR" { U3.iot_208 RS4.p1 }
267	  net "SD_CAS"   class "SDADDR" { RS4.p2 U4.cas }
268	  net "SD_WE_F"  class "SDADDR" { U3.iot_197_gbin1 RS5.p1 }
269	  net "SD_WE"    class "SDADDR" { RS5.p2 U4.we }
270	  net "SD_CKE_F" class "SDADDR" { U3.iot_177 RS6.p1 }
271	  net "SD_CKE"   class "SDADDR" { RS6.p2 U4.cke }
272	  net "SD_CK_F"  class "SDCLK"  { U3.iot_198_gbin0 RS1.p1 }
273	  net "SD_CK"    class "SDCLK"  { RS1.p2 U4.clk }
274	}
